-- Service: tasks  (per cell)
-- GENERATED by tools/split.py from plan/db/*.sql. Edit the source files or split.py, then re-run.
-- Load order: _prelude.sql, tasks.sql, tasks.later.sql, _epilogue.sql
CREATE TABLE task_merges (
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  id uuid PRIMARY KEY,
  source_task_id uuid NOT NULL REFERENCES tasks(id),
  target_task_id uuid NOT NULL REFERENCES tasks(id),
  merged_by uuid /* id -> identity.users */,
  merged_at timestamptz NOT NULL DEFAULT now(),
  CHECK (source_task_id <> target_task_id)
);

CREATE TABLE task_recurrences (
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  task_id uuid NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  mode text NOT NULL CHECK (mode IN ('schedule','on_completion')),
  rrule text,                                            -- iCal RRULE for schedule mode
  interval_days integer,
  weekdays smallint[],
  next_create_policy text NOT NULL DEFAULT 'new_task' CHECK (next_create_policy IN ('new_task','reopen')),
  copy_assignees boolean NOT NULL DEFAULT true,
  next_run_at timestamptz,
  last_created_task_id uuid REFERENCES tasks(id),
  active boolean NOT NULL DEFAULT true,
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1,
  PRIMARY KEY (workspace_id, task_id),
  CHECK (mode <> 'schedule' OR rrule IS NOT NULL OR interval_days IS NOT NULL)
);

CREATE INDEX task_recurrences_due ON task_recurrences (next_run_at) WHERE active;

-- =============================================================================
-- 13. BUG TRACKING and PROJECT MESSAGING  (reviewer comments 2 and 3, C-11)  ASSUMED
-- Bug = task with task_type 'Bug' (seed it). Extra bug fields live here so they stay typed and filterable.
-- =============================================================================
CREATE TABLE releases (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  container_id uuid NOT NULL /* id -> hierarchy.containers */,     -- project (space/folder/list)
  name text NOT NULL, status text NOT NULL DEFAULT 'planned' CHECK (status IN ('planned','in_progress','released','cancelled')),
  planned_at date, released_at date,
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1,
  UNIQUE (container_id, name)
);
